const imgStar = "https://www.figma.com/api/mcp/asset/fc954b6a-9da5-4844-b6a0-7214cbb0032e.svg";
const imgX = "https://www.figma.com/api/mcp/asset/4077e3fa-5fce-4cf3-b80e-49179ca9d1f4.svg";

type ButtonProps = {
  className?: string;
  hasIconEnd?: boolean;
  hasIconStart?: boolean;
  iconEnd?: React.ReactNode | null;
  iconStart?: React.ReactNode | null;
  label?: string;
  size?: "Medium";
  state?: "Default";
  variant?: "Primary";
};

function Button({ className, hasIconEnd = false, hasIconStart = false, iconEnd = null, iconStart = null, label = "Button", size = "Medium", state = "Default", variant = "Primary" }: ButtonProps) {
  return (
    <div className={className || "bg-[var(--sds-color-background-brand-default,#2c2c2c)] border-[length:var(--sds-size-stroke-border,1px)] border-[var(--sds-color-border-brand-default,#2c2c2c)] border-solid content-stretch flex gap-[var(--sds-size-space-200,8px)] items-center justify-center overflow-clip p-[var(--sds-size-space-300,12px)] relative rounded-[var(--sds-size-radius-200,8px)]"} data-node-id="4185:3779">
      {hasIconStart &&
        (iconStart || (
          <div className="relative shrink-0 size-[16px]" data-node-id="4185:3780" data-name="Star">
            <img alt="" className="absolute block inset-0 max-w-none size-full" src={imgStar} />
          </div>
        ))}
      <p className="[word-break:break-word] font-[family-name:var(--sds-typography-body-font-family,'Inter:Regular')] font-[var(--sds-typography-body-font-weight-regular,400)] leading-none not-italic relative shrink-0 text-[color:var(--sds-color-text-brand-on-brand,#f5f5f5)] text-[length:var(--sds-typography-body-size-medium,16px)] whitespace-nowrap" data-node-id="4185:3781">
        {label}
      </p>
      {hasIconEnd &&
        (iconEnd || (
          <div className="relative shrink-0 size-[16px]" data-node-id="4185:3782" data-name="X">
            <img alt="" className="absolute block inset-0 max-w-none size-full" src={imgX} />
          </div>
        ))}
    </div>
  );
}
